insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_84_v1'
from (values
('127.680.d.1.A',3,'Which behavior would most improve a computer technician''s chances of keeping a job?','["arriving on time and finishing assigned work", "ignoring supervisors", "skipping shifts", "hiding mistakes"]'::jsonb,0,'Reliability supports advancement.','original'),
('127.680.d.1.A',4,'A technician wants a promotion. Which habit best builds that case over time?','["avoiding training", "consistently exceeding expectations and taking on new tasks", "doing the minimum", "blaming coworkers"]'::jsonb,1,'Initiative and results earn advancement.','original'),
('127.680.d.1.B',3,'A technician who accepts a new software tool without complaint is showing:','["stubbornness", "impatience", "flexibility", "carelessness"]'::jsonb,2,'Flexibility means adapting to change.','original'),
('127.680.d.1.B',4,'A coworker suggests a different repair method. Open-mindedness means you should:','["reject it at once", "ignore the coworker", "argue until they quit", "consider the idea fairly before deciding"]'::jsonb,3,'Open-minded people weigh new ideas.','original'),
('127.680.d.1.C',3,'Reading a printer''s installation guide before setting it up is an example of:','["using reading skills to follow technical directions", "guessing", "wasting time", "avoiding the task"]'::jsonb,0,'Reading guides prevents mistakes.','original'),
('127.680.d.1.C',4,'A clear repair note written for the next technician should be:','["vague and long", "brief, specific and easy to follow", "left blank", "full of slang"]'::jsonb,1,'Good notes help the next reader.','original'),
('127.680.d.1.D',3,'Which is a nonverbal skill that shows you are listening to a customer?','["crossing your arms and sighing", "turning away", "making eye contact and nodding", "looking at your phone"]'::jsonb,2,'Body language signals attention.','original'),
('127.680.d.1.D',4,'A customer is upset about a broken laptop. Which response is best?','["joke about the problem", "walk away", "raise your voice", "stay calm, speak politely and explain the next steps"]'::jsonb,3,'Calm, clear speech reduces conflict.','original'),
('127.680.d.1.E',3,'A computer will not start. A good problem solver begins by:','["gathering facts about what happened", "guessing a random part", "giving up", "throwing it away"]'::jsonb,0,'Facts guide a diagnosis.','original'),
('127.680.d.1.E',4,'Thinking critically about a repair means you:','["avoid testing", "test an idea with evidence before accepting it", "copy others without checking", "accept the first guess"]'::jsonb,1,'Evidence supports conclusions.','original'),
('127.680.d.1.F',3,'A good team member on a network project:','["keeps all knowledge secret", "leaves early daily", "shares information and does a fair share of the work", "takes all credit"]'::jsonb,2,'Teams need cooperation.','original'),
('127.680.d.1.F',4,'Which action shows leadership during a team repair job?','["giving no directions", "working alone out of sight", "ignoring the plan", "organizing tasks and encouraging others"]'::jsonb,3,'Leaders guide and support.','original'),
('127.680.d.1.G',3,'Before opening a computer case, a technician should first:','["power it off and unplug it", "touch the power supply", "spray it with water", "leave it running"]'::jsonb,0,'Unplugging prevents shock and damage.','original'),
('127.680.d.1.G',4,'Which item protects sensitive parts from static electricity?','["a wool sweater", "an anti-static wrist strap", "a metal ruler", "a rubber mallet"]'::jsonb,1,'A strap grounds the technician.','original'),
('127.680.d.1.H',3,'Copying paid software for friends without permission is:','["a normal practice", "required by law", "illegal and unethical", "encouraged by employers"]'::jsonb,2,'Piracy breaks license law.','original'),
('127.680.d.1.H',4,'A technician finds a customer''s private photos while repairing a drive. The ethical action is to:','["copy them", "share them", "post them online", "leave them alone and keep them confidential"]'::jsonb,3,'Customer privacy must be respected.','original'),
('127.680.d.1.I',3,'Planning a big upgrade for many computers is easier when you:','["break the project into steps with deadlines", "wait for problems", "skip scheduling", "start without a plan"]'::jsonb,0,'Schedules organize projects.','original'),
('127.680.d.1.I',4,'Time management for a technician with five repair tickets means:','["working randomly", "handling the most urgent tickets first", "ignoring due dates", "doing only the easiest"]'::jsonb,1,'Prioritizing saves time.','original'),
('127.680.d.2.A',3,'A work order for a computer repair usually lists:','["a recipe", "vacation plans", "the problem, the customer and the work to be done", "a song"]'::jsonb,2,'Work orders describe the job.','original'),
('127.680.d.2.A',4,'After finishing a repair, the technician should update the work order with:','["a joke", "a new password for the customer", "nothing at all", "the parts used and the time spent"]'::jsonb,3,'Records support billing.','original'),
('127.680.d.2.B',3,'To estimate the cost of a repair, a technician adds the price of parts and the cost of:','["labor", "music", "parking", "weather"]'::jsonb,0,'Cost includes parts and labor.','original'),
('127.680.d.2.B',4,'A part costs $40, labor is 2 hours at $30 per hour. What is the estimate?','["$80", "$100", "$130", "$70"]'::jsonb,1,'40 + 60 = 100.','original'),
('127.680.d.2.C',3,'A schematic diagram shows:','["a customer''s address", "the floor plan of a school", "how circuit parts are connected", "the weather"]'::jsonb,2,'Schematics show connections.','original'),
('127.680.d.2.C',4,'Which document helps a technician find the correct way to install a specific motherboard?','["a poster", "a menu", "a map of the city", "the manufacturer''s installation manual"]'::jsonb,3,'Manuals give model-specific steps.','original'),
('127.680.d.3.A',3,'When using a power screwdriver on a computer case, a technician should:','["use the right bit and wear eye protection", "work barefoot", "hold the part in one hand near the tip", "remove the guard"]'::jsonb,0,'Safe tool use prevents injuries.','original'),
('127.680.d.3.A',4,'Why should a technician keep a work area free of clutter?','["to hide tools", "to prevent trips and tool or part damage", "to avoid cleaning later", "to look busy"]'::jsonb,1,'A clear area is safer.','original'),
('127.680.d.3.B',3,'Which source can a technician use to look up a part''s specifications?','["a menu", "a cartoon", "the manufacturer''s website", "a calendar"]'::jsonb,2,'Official sites list specs.','original'),
('127.680.d.3.B',4,'A repair guide online conflicts with the maker''s manual. The technician should trust:','["a guess", "the unverified forum post", "the oldest comment", "the manufacturer''s documentation"]'::jsonb,3,'Official documentation is most reliable.','original'),
('127.680.d.3.C',3,'Old batteries and monitors contain materials that should be:','["taken to a proper recycling or disposal site", "buried in the yard", "thrown in a creek", "burned in a barrel"]'::jsonb,0,'Hazardous materials need special handling.','original'),
('127.680.d.3.C',4,'Which document gives handling and disposal information for a chemical used in cleaning electronics?','["a warranty card", "the Safety Data Sheet (SDS)", "a price tag", "a receipt"]'::jsonb,1,'The SDS covers hazards and disposal.','original'),
('127.680.d.3.D',3,'Staying informed about new technology helps a computer technician:','["lose customers", "avoid learning", "keep skills useful for future jobs", "repeat old work"]'::jsonb,2,'Skills must keep up with change.','original'),
('127.680.d.3.D',4,'A technician hears about a new type of memory. A good next step is to:','["ignore all news", "delete the article", "pretend it does not exist", "read about how it works and where it is used"]'::jsonb,3,'Research keeps knowledge current.','original'),
('127.680.d.4.A',3,'Which pair of electrical quantities can a technician read with a handheld multimeter?','["voltage and resistance", "file names", "screen color", "font size"]'::jsonb,0,'Multimeters measure electrical values.','original'),
('127.680.d.4.A',4,'A technician measures 5 volts across a part with 10 ohms of resistance. The current is:','["50 amperes", "0.5 amperes", "15 amperes", "2 amperes"]'::jsonb,1,'5 divided by 10 equals 0.5.','original'),
('127.680.d.4.B',3,'A bus in a computer is a:','["kind of printer", "type of keyboard", "pathway that carries data between components", "school vehicle"]'::jsonb,2,'Buses move data and signals.','original'),
('127.680.d.4.B',4,'A digital circuit works with signals that are either:','["hot or cold only", "blue or green", "loud or quiet", "on or off"]'::jsonb,3,'Digital uses two states.','original'),
('127.680.d.4.C',3,'The brain of the computer that runs instructions is the:','["CPU", "mouse", "speaker", "monitor"]'::jsonb,0,'The CPU processes instructions.','original'),
('127.680.d.4.C',4,'The term for data that a computer temporarily holds while running programs is:','["driver", "memory", "wallpaper", "cable"]'::jsonb,1,'Memory holds active data.','original'),
('127.680.d.4.D',3,'Which component stores your files even when the computer is turned off?','["the sound card", "the fan", "the hard drive or SSD", "RAM"]'::jsonb,2,'Drives provide permanent storage.','original'),
('127.680.d.4.D',4,'A video card is mainly responsible for:','["cooling the case", "storing email", "reading disks", "producing images for the display"]'::jsonb,3,'GPUs handle graphics output.','original'),
('127.680.d.4.E',3,'A printer is printing blank pages. A technician should first check:','["the ink or toner", "the desktop theme", "the keyboard", "the speakers"]'::jsonb,0,'Empty supplies cause blank pages.','original'),
('127.680.d.4.E',4,'A mouse pointer will not move. Which is a good simple test?','["buy a new monitor", "plug it into a different USB port", "reinstall the OS", "replace the CPU"]'::jsonb,1,'Swapping ports isolates the issue.','original'),
('127.680.d.5.A',3,'When building a basic computer, which part is mounted to the case first in many builds?','["the printer", "the keyboard", "the power supply or motherboard standoffs", "the monitor stand"]'::jsonb,2,'Core parts go into the case first.','original'),
('127.680.d.5.A',4,'Before powering on a new build, a technician should confirm:','["a game is installed", "the case is painted", "the wallpaper is set", "all power connectors are firmly seated"]'::jsonb,3,'Loose connectors prevent startup.','original'),
('127.680.d.5.B',3,'After connecting a new printer, the computer usually needs the right:','["driver", "sound effect", "screen saver", "wallpaper"]'::jsonb,0,'Drivers let the OS use the device.','original'),
('127.680.d.5.B',4,'To share a printer with others on a network, the technician must:','["hide it", "configure it for network access", "unplug it", "remove its ink"]'::jsonb,1,'Network printing needs setup.','original'),
('127.680.d.6.A',3,'A message reading ''No boot device found'' most likely points to a problem with the:','["speaker volume", "keyboard layout", "storage drive or boot settings", "monitor brightness"]'::jsonb,2,'The system cannot find a startup drive.','original'),
('127.680.d.6.A',4,'A computer repeatedly restarts before reaching the desktop. Which hardware cause is plausible?','["an old wallpaper", "a large desktop icon", "a bent paper clip", "failing memory or an overheating processor"]'::jsonb,3,'Hardware faults can cause reboot loops.','original'),
('127.680.d.6.B',3,'Short beeps heard during power-up come from the computer''s:','["self-test routine", "screen saver", "word processor", "printer driver"]'::jsonb,0,'Beeps report self-test results.','original'),
('127.680.d.6.B',4,'To find what a pattern of beeps means for a certain motherboard, a technician looks in the:','["cookbook", "BIOS or motherboard manual", "sports schedule", "phone directory"]'::jsonb,1,'Codes vary by maker.','original'),
('127.680.d.6.C',3,'A device sends an interrupt request so that the:','["drive is erased", "fan stops", "CPU will pause and handle its need", "screen turns off"]'::jsonb,2,'Interrupts request attention.','original'),
('127.680.d.6.C',4,'Two devices request attention at once. The CPU decides which to serve first using:','["the device color", "coin flips", "the alphabet", "assigned priority levels"]'::jsonb,3,'Priority levels order the requests.','original'),
('127.680.d.6.D',3,'A program that checks memory for errors is a:','["diagnostic tool", "music player", "game", "photo editor"]'::jsonb,0,'Diagnostics test hardware.','original'),
('127.680.d.6.D',4,'Which result from a hard drive diagnostic would be a warning sign?','["a normal temperature", "a growing count of bad sectors", "a clean boot", "a quick response"]'::jsonb,1,'Bad sectors signal drive failure.','original'),
('127.680.d.6.E',3,'An operating system that keeps crashing after an update may need to be:','["covered with tape", "thrown out the window", "repaired or rolled back to an earlier state", "left alone forever"]'::jsonb,2,'Rollback can undo a bad update.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_84_v1'
from (values
('127.680.d.6.E',4,'Startup errors that appear only after loading Windows often come from:','["a missing wall outlet", "the room temperature only", "a loose chair", "corrupted system files or faulty drivers"]'::jsonb,3,'OS files and drivers fail after loading.','original'),
('127.680.d.6.F',3,'A computer will not power on and no lights appear. This points toward a:','["hardware problem", "browser bookmark issue", "wallpaper issue", "software setting"]'::jsonb,0,'No power is usually hardware.','original'),
('127.680.d.6.F',4,'A program crashes but the hardware tests pass. The cause is more likely:','["a damaged motherboard", "software", "a bent connector", "a broken fan"]'::jsonb,1,'Passing hardware tests suggests software.','original'),
('127.680.d.6.G',3,'BIOS stands for:','["Binary Internet Output Source", "Base Internal Operating Setup", "Basic Input/Output System", "Basic Interface Online System"]'::jsonb,2,'BIOS starts and configures hardware.','original'),
('127.680.d.6.G',4,'Before updating the BIOS, a technician should make sure the computer will:','["be turned off midway", "be unplugged", "run a game", "not lose power during the update"]'::jsonb,3,'Power loss can ruin the BIOS.','original'),
('127.680.d.6.H',3,'Defragmenting a traditional hard drive can help by:','["placing file pieces closer together for faster access", "deleting all files", "adding more memory", "changing the screen size"]'::jsonb,0,'Fewer scattered pieces speeds reads.','original'),
('127.680.d.6.H',4,'Clearing a browser''s cache can help fix:','["a failed fan", "pages that load old or broken content", "a loose cable", "a dead monitor"]'::jsonb,1,'Old cached files can cause display errors.','original'),
('127.680.d.6.I',3,'Before touching a customer''s computer, a good first step is to:','["reformat the drive", "unplug everything", "ask the customer what symptoms they noticed", "start changing settings"]'::jsonb,2,'User details narrow the cause.','original'),
('127.680.d.6.I',4,'Which question helps a technician learn when a problem started?','["''Can I take a break?''", "''What is your favorite show?''", "''Do you like my shirt?''", "''What changed right before the issue began?''"]'::jsonb,3,'Recent changes often cause problems.','original'),
('127.680.d.6.J',3,'A computer with a bad stick of RAM is usually repaired by:','["replacing the faulty memory module", "changing the wallpaper", "repainting the case", "cleaning the keyboard only"]'::jsonb,0,'Bad RAM is replaced.','original'),
('127.680.d.6.J',4,'After replacing a power supply, a technician should:','["hide the old part", "test the system and confirm it runs correctly", "leave without testing", "skip documentation"]'::jsonb,1,'Testing confirms the fix.','original'),
('127.680.d.6.K',3,'If an application is damaged, a common fix is to:','["unplug the router", "shake the computer", "uninstall it and install it again", "buy a new desk"]'::jsonb,2,'Reinstalling replaces damaged files.','original'),
('127.680.d.6.K',4,'Before reinstalling software, a technician should make sure to:','["skip the license", "erase the data", "throw away the disc", "back up the customer''s data and save the license key"]'::jsonb,3,'Data and keys must be kept.','original'),
('127.680.d.6.L',3,'A backup is a:','["copy of data stored in a separate place", "computer game", "type of virus", "kind of cable"]'::jsonb,0,'Backups protect against loss.','original'),
('127.680.d.6.L',4,'A backup stored on the same drive that failed is of little help because:','["it is encrypted", "the copy is lost with the original", "it is too clean", "it is too fast"]'::jsonb,1,'Backups should be stored separately.','original'),
('127.680.d.6.M',3,'Windows Safe Mode starts the computer with:','["a faster CPU", "all games loaded", "only basic drivers and services", "extra memory"]'::jsonb,2,'Safe Mode limits what loads.','original'),
('127.680.d.6.M',4,'System Restore can help by:','["changing the monitor", "deleting all photos", "increasing RAM", "returning system files to an earlier working point"]'::jsonb,3,'Restore points undo recent changes.','original'),
('127.680.d.6.N',3,'Which part of an operating system manages how programs share the CPU?','["the scheduler or kernel", "the clock widget", "the wallpaper", "the volume slider"]'::jsonb,0,'The kernel schedules processes.','original'),
('127.680.d.6.N',4,'Regular maintenance of an operating system includes:','["disabling all security", "installing updates and removing unneeded files", "deleting system folders", "leaving it forever unchanged"]'::jsonb,1,'Updates and cleanup keep it healthy.','original'),
('127.680.d.6.O',3,'Knowing how the operating system manages files helps a support technician:','["design a building", "bake bread", "recover and organize user files properly", "paint a car"]'::jsonb,2,'File system knowledge aids support.','original'),
('127.680.d.6.O',4,'When a user cannot find a saved document, a technician with OS knowledge could:','["reinstall the monitor", "buy another computer", "replace the mouse", "search by file name or date and check the Recycle Bin"]'::jsonb,3,'OS tools can locate missing files.','original'),
('127.680.d.7.A',3,'Before buying new accounting software, a company should:','["test whether it does the tasks they need", "pick the cheapest box", "choose a random one", "pick by color"]'::jsonb,0,'Functionality testing prevents bad purchases.','original'),
('127.680.d.7.A',4,'A trial version of software is useful because it lets a user:','["skip installation", "check functionality before paying", "get free hardware", "avoid reading"]'::jsonb,1,'Trials allow testing.','original'),
('127.680.d.7.B',3,'A software license is:','["a hardware part", "a type of cable", "a legal agreement that lets you use a program", "a computer virus"]'::jsonb,2,'Licenses grant permission to use.','original'),
('127.680.d.7.B',4,'A company has 10 licenses but needs the program on 25 computers. A technician should:','["share one key with everyone", "remove the license check", "install it anyway", "buy more licenses before installing"]'::jsonb,3,'Use must match licenses owned.','original'),
('127.680.d.7.C',3,'To install an application, a technician commonly runs the program''s:','["setup or installer file", "backup file", "wallpaper", "help desk phone"]'::jsonb,0,'Installers place program files.','original'),
('127.680.d.7.C',4,'Which resource helps a technician install a program correctly?','["an old receipt", "the vendor''s installation instructions", "a guess", "a random video"]'::jsonb,1,'Vendor steps are most reliable.','original'),
('127.680.d.7.D',3,'If an installation stops partway because of an error, a technician should first:','["ignore it", "restart repeatedly", "read the error message and check requirements", "delete the OS"]'::jsonb,2,'Errors explain the failure.','original'),
('127.680.d.7.D',4,'After a failed installation leaves a computer unstable, a way to recover is to:','["do nothing", "add more programs", "turn off updates", "use a restore point or uninstall leftover files"]'::jsonb,3,'Recovery returns the system to a stable state.','original'),
('127.680.d.7.E',3,'Customizing software for a user might include:','["changing the settings or layout to fit their work", "replacing the keyboard", "erasing the license", "redesigning the building"]'::jsonb,0,'Customization adjusts preferences.','original'),
('127.680.d.7.E',4,'Before customizing a company-wide program, a technician should:','["skip testing", "confirm the change is approved and documented", "delete the defaults", "make secret changes"]'::jsonb,1,'Changes need approval.','original'),
('127.680.d.7.F',3,'Writing down each step of an installation helps because:','["it makes software slower", "it hides mistakes", "others can repeat or troubleshoot it later", "it wastes time"]'::jsonb,2,'Documentation supports future work.','original'),
('127.680.d.7.F',4,'A good installation record includes the software version and the:','["weather forecast", "technician''s lunch", "room color", "date and settings used"]'::jsonb,3,'Details allow reproduction.','original'),
('127.680.d.7.G',3,'Antivirus software helps protect a computer by:','["detecting and removing malicious programs", "cooling the CPU", "increasing screen size", "adding speakers"]'::jsonb,0,'Antivirus finds malware.','original'),
('127.680.d.7.G',4,'For security software to work well, it must be:','["turned off often", "kept updated with the latest definitions", "never updated", "installed on paper"]'::jsonb,1,'Updates cover new threats.','original'),
('127.680.d.8.A',3,'A computer needs a network interface card to:','["play music only", "cool the CPU", "connect to a network", "print photos"]'::jsonb,2,'The NIC links to the network.','original'),
('127.680.d.8.A',4,'The speed and type of cable a network supports are part of its:','["keyboard layout", "mouse settings", "screen colors", "interface requirements"]'::jsonb,3,'Interfaces must match the network.','original'),
('127.680.d.8.B',3,'A computer on a wired network is usually connected using:','["an Ethernet cable", "a phone book", "a pencil", "a speaker wire only"]'::jsonb,0,'Ethernet carries network data.','original'),
('127.680.d.8.B',4,'To get an address automatically, a computer on a network can be set to use:','["VGA", "DHCP", "USB", "HDMI"]'::jsonb,1,'DHCP assigns addresses.','original'),
('127.680.d.8.C',3,'A tool that tests whether another computer responds is:','["solitaire", "notepad", "ping", "paint"]'::jsonb,2,'Ping tests reachability.','original'),
('127.680.d.8.C',4,'A computer shows ''limited connectivity.'' A technician should check:','["the screen saver", "the mouse pad", "the printer paper", "the cable and the IP settings"]'::jsonb,3,'Connection and addressing are key.','original'),
('127.680.d.9.A',3,'A disaster recovery plan for a small shop''s computers should list:','["who restores data and in what order", "favorite snacks", "car colors", "party dates"]'::jsonb,0,'Plans define roles and order.','original'),
('127.680.d.9.A',4,'A key element of a recovery plan is knowing where the:','["parking spaces are", "latest backups are stored", "break room is", "lunch menu is"]'::jsonb,1,'Backups are needed to recover.','original'),
('127.680.d.9.B',3,'A preventive maintenance plan for computers could include:','["ignoring dust", "waiting for failure", "regularly cleaning dust and checking updates", "never updating"]'::jsonb,2,'Regular tasks prevent failures.','original'),
('127.680.d.9.B',4,'Scheduling maintenance in advance helps by:','["removing the need for backups", "causing more downtime", "making repairs longer", "finding small problems before they become failures"]'::jsonb,3,'Prevention reduces breakdowns.','original'),
('127.681.d.1.A',3,'Researching a telecommunications job should include finding out its typical:','["duties and required skills", "holiday decorations", "parking rules", "cafeteria menu"]'::jsonb,0,'Job research covers duties and skills.','original'),
('127.681.d.1.A',4,'Which source gives accurate information on what network technicians do?','["a game chat", "the Occupational Outlook Handbook", "a rumor", "a joke site"]'::jsonb,1,'Government job guides describe duties.','original'),
('127.681.d.1.B',3,'A personal career plan for networking might list:','["pet names", "vacation photos", "courses, certifications and work experience to gain", "favorite songs"]'::jsonb,2,'Plans list steps toward a goal.','original'),
('127.681.d.1.B',4,'Which entry best belongs in a five-year career plan?','["watch more television", "wait for a job to appear", "avoid training", "earn a networking certification and complete an internship"]'::jsonb,3,'Goals should be specific and actionable.','original'),
('127.681.d.1.C',3,'The top of a resume usually contains the applicant''s:','["name and contact information", "lunch order", "favorite color", "grades from first grade"]'::jsonb,0,'Contact details come first.','original'),
('127.681.d.1.C',4,'On a resume for a network technician job, which is the best item to list?','["a school locker number", "a class project that built and configured a small network", "a list of video games", "a funny nickname"]'::jsonb,1,'Relevant projects show skill.','original'),
('127.681.d.2.A',3,'Explaining a network outage to a customer works best when you:','["avoid eye contact", "talk very fast", "use plain words and avoid unneeded jargon", "use only acronyms"]'::jsonb,2,'Clear language builds understanding.','original'),
('127.681.d.2.A',4,'When writing an email to report a completed network install, the message should be:','["written in all capitals", "full of errors", "rude and short", "professional, accurate and organized"]'::jsonb,3,'Professional writing reflects well on the technician.','original'),
('127.681.d.2.B',3,'A work order for a network installation tells the technician:','["what to install and where", "how to dance", "who won a game", "what to eat"]'::jsonb,0,'Work orders define the job.','original'),
('127.681.d.2.B',4,'A completed work order should be signed or noted to show that:','["the weather was nice", "the job was finished", "the customer was late", "the toolbox was heavy"]'::jsonb,1,'Completion is documented.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_84_v1'
from (values
('127.681.d.2.C',3,'A cable run quote should include the cost of cable, connectors and:','["lunch for pets", "sports tickets", "labor", "a new car"]'::jsonb,2,'Estimates include labor.','original'),
('127.681.d.2.C',4,'A job needs 200 feet of cable at $0.50 per foot plus $60 labor. What is the estimate?','["$100", "$110", "$260", "$160"]'::jsonb,3,'100 + 60 = 160.','original'),
('127.681.d.2.D',3,'A network diagram helps a technician:','["see how devices are connected", "choose paint", "pick a font", "plan a meal"]'::jsonb,0,'Diagrams show device relationships.','original'),
('127.681.d.2.D',4,'A floor plan marked with cable routes would help a technician decide:','["what to wear", "where to run cables and place equipment", "how to spell", "what music to play"]'::jsonb,1,'Plans guide installation.','original'),
('127.681.d.3.A',3,'An analog signal is one that:','["cannot carry sound", "has only two values", "changes smoothly over a range of values", "is always zero"]'::jsonb,2,'Analog varies continuously.','original'),
('127.681.d.3.A',4,'A digital signal sent over a network is made up of:','["only colors", "only sound waves", "random letters", "bits that are 0 or 1"]'::jsonb,3,'Digital data uses binary.','original'),
('127.681.d.3.B',3,'An IP address is converted into binary because computers:','["process data as 0s and 1s", "dislike decimals", "use only letters", "cannot read numbers"]'::jsonb,0,'Binary is the computer''s language.','original'),
('127.681.d.3.B',4,'The binary octet 11000000 equals what decimal number?','["64", "192", "128", "224"]'::jsonb,1,'128 + 64 = 192.','original'),
('127.681.d.3.C',3,'On a network, data is usually divided into small pieces called:','["slides", "pages", "packets", "chapters"]'::jsonb,2,'Data travels in packets.','original'),
('127.681.d.3.C',4,'Compared with a phone call over a traditional line, a data packet network:','["cannot carry data", "uses one fixed circuit", "sends only audio", "sends data in pieces that can take different paths"]'::jsonb,3,'Packet switching splits and routes data.','original'),
('127.681.d.3.D',3,'The OSI reference model for network communication is divided into how many layers?','["seven", "nine", "five", "three"]'::jsonb,0,'The OSI model has seven layers.','original'),
('127.681.d.3.D',4,'The layer of the OSI model that deals with cables and electrical signals is the:','["transport layer", "physical layer", "session layer", "application layer"]'::jsonb,1,'Layer 1 covers physical media.','original'),
('127.681.d.3.E',3,'TCP/IP is a set of:','["computer games", "power cables", "rules that let computers communicate on a network", "wallpapers"]'::jsonb,2,'TCP/IP defines communication.','original'),
('127.681.d.3.E',4,'Subnetting a network is done to:','["remove all routers", "erase IP addresses", "double the cable length", "divide it into smaller, manageable parts"]'::jsonb,3,'Subnets organize and limit traffic.','original'),
('127.681.d.3.F',3,'A home Wi-Fi network is an example of a:','["private network", "television channel", "public park network only", "global search engine"]'::jsonb,0,'Private networks are controlled by owners.','original'),
('127.681.d.3.F',4,'The internet differs from a company''s internal network because it is:','["limited to one room", "open to the public", "owned by one firm", "unconnected to others"]'::jsonb,1,'The internet is public.','original'),
('127.681.d.3.G',3,'Wi-Fi allows devices to connect to a network:','["using sound only", "through paper", "using radio waves instead of cables", "only with cables"]'::jsonb,2,'Wireless uses radio signals.','original'),
('127.681.d.3.G',4,'The group of standards that govern Wi-Fi is known as:','["IEEE 1394", "RS-232", "USB 3.0", "IEEE 802.11"]'::jsonb,3,'802.11 defines wireless LANs.','original'),
('127.681.d.3.H',3,'A network that covers one building or campus is a:','["local area network (LAN)", "wide area network", "storage array", "personal bus"]'::jsonb,0,'A LAN is local.','original'),
('127.681.d.3.H',4,'A network connecting offices in different cities is a:','["single LAN", "wide area network (WAN)", "sound card", "USB hub"]'::jsonb,1,'WANs span large distances.','original'),
('127.681.d.3.I',3,'Organizations that publish standards for data communication include:','["Disney and Nike", "a bakery and a gym", "IEEE and ANSI", "a toy store and a theater"]'::jsonb,2,'IEEE and ANSI set technical standards.','original'),
('127.681.d.3.I',4,'Standards are important in networking because they:','["raise prices", "limit speed", "make all devices identical", "let equipment from different makers work together"]'::jsonb,3,'Standards ensure compatibility.','original'),
('127.681.d.3.J',3,'Faster wireless networks and more connected devices may bring benefits such as:','["greater speed and convenience", "fewer devices", "no data", "slower service by design"]'::jsonb,0,'Technology can improve access.','original'),
('127.681.d.3.J',4,'A problem that grows as more devices connect to networks is:','["less data", "increased security risk", "fewer standards", "slower thinking"]'::jsonb,1,'More devices create more targets.','original'),
('127.681.d.4.A',3,'What is the main job of a network router?','["cool a server", "store files", "direct data between different networks", "print photos"]'::jsonb,2,'Routers forward packets between networks.','original'),
('127.681.d.4.A',4,'A switch differs from a hub because a switch:','["has no ports", "sends data to every port", "stores no addresses", "sends data only to the device that needs it"]'::jsonb,3,'Switches forward selectively.','original'),
('127.681.d.4.B',3,'Windows Server and Linux are examples of:','["network operating systems", "cable types", "wireless antennas", "printers"]'::jsonb,0,'They manage network resources.','original'),
('127.681.d.4.B',4,'A network operating system is designed to:','["only edit photos", "manage users, files and resources shared across a network", "only play audio", "only run games"]'::jsonb,1,'NOS tools support many users.','original'),
('127.681.d.4.C',3,'Which cable carries data as pulses of light?','["twisted pair", "coaxial cable", "fiber-optic cable", "power cord"]'::jsonb,2,'Fiber uses light signals.','original'),
('127.681.d.4.C',4,'A common cable for Ethernet in offices is:','["extension cord", "garden hose", "speaker wire", "twisted-pair cable"]'::jsonb,3,'Twisted pair is widely used.','original'),
('127.681.d.4.D',3,'The connector used on a standard Ethernet cable is the:','["RJ-45", "USB-A", "VGA", "HDMI"]'::jsonb,0,'Ethernet uses RJ-45.','original'),
('127.681.d.4.D',4,'Telephone lines in the United States traditionally use which connector?','["DVI", "RJ-11", "RJ-45", "SATA"]'::jsonb,1,'RJ-11 is the phone connector.','original'),
('127.681.d.4.E',3,'In a star topology, all devices connect to:','["nothing", "a single long cable", "a central switch or hub", "each other in a ring"]'::jsonb,2,'Star uses a central device.','original'),
('127.681.d.4.E',4,'In a bus topology, devices share:','["separate cables to each other", "wireless links only", "a switch per device", "one common backbone cable"]'::jsonb,3,'Bus uses one shared line.','original'),
('127.681.d.4.F',3,'A protocol that sets up a session before sending data is called:','["connection-oriented", "connectionless", "wireless-only", "unplugged"]'::jsonb,0,'Connection-oriented sets up first.','original'),
('127.681.d.4.F',4,'UDP is considered connectionless because it:','["needs a handshake", "sends data without first setting up a connection", "guarantees delivery", "always checks every packet"]'::jsonb,1,'UDP skips setup.','original'),
('127.681.d.4.G',3,'The ping utility uses which protocol to test connectivity?','["FTP", "SMTP", "ICMP", "HTTP"]'::jsonb,2,'Ping sends ICMP echo messages.','original'),
('127.681.d.4.G',4,'Which tool shows the route packets take to a destination?','["notepad", "defrag", "paint", "traceroute"]'::jsonb,3,'Traceroute lists hops.','original'),
('127.681.d.4.H',3,'A technician can validate a local network card is working by pinging:','["the loopback address 127.0.0.1", "the printer toner", "the moon", "a random website only"]'::jsonb,0,'The loopback tests the TCP/IP stack.','original'),
('127.681.d.4.H',4,'If pinging an IP address works but pinging a website name fails, the likely problem is with:','["the monitor", "name resolution (DNS)", "the keyboard", "the power cord"]'::jsonb,1,'DNS translates names to addresses.','original'),
('127.681.d.4.I',3,'Which practice improves network security?','["disabling firewalls", "sharing passwords", "using strong passwords and updates", "leaving defaults"]'::jsonb,2,'Basic hygiene reduces risk.','original'),
('127.681.d.4.I',4,'Changing the default router password is important because defaults are:','["too long", "easy to forget", "unneeded", "publicly known to attackers"]'::jsonb,3,'Default credentials are widely published.','original'),
('127.681.d.5.A',3,'Comparing a star network with a ring network is an example of:','["analyzing types of networks", "baking", "gardening", "painting"]'::jsonb,0,'Analysis compares features.','original'),
('127.681.d.5.A',4,'A network component that connects the local network to the internet is the:','["keyboard", "router", "speaker", "mouse"]'::jsonb,1,'Routers link networks to the internet.','original'),
('127.681.d.5.B',3,'A busy office with many users probably needs a network with more:','["windows", "decorations", "bandwidth", "chairs"]'::jsonb,2,'More users need more capacity.','original'),
('127.681.d.5.B',4,'When choosing between wired and wireless for a fixed desktop that needs a stable fast link, a technician would likely pick:','["wireless always", "dial-up", "no network", "wired Ethernet"]'::jsonb,3,'Wired is often steadier and faster.','original'),
('127.681.d.6.A',3,'Before building a network, planning documents should show the:','["layout, equipment and cable paths", "pet policy", "vacation days", "lunch menu"]'::jsonb,0,'Plans guide the build.','original'),
('127.681.d.6.A',4,'A bill of materials for a network project lists:','["parking permits", "all parts to be purchased and their quantities", "office plants", "employees'' birthdays"]'::jsonb,1,'BOMs support ordering.','original'),
('127.681.d.6.B',3,'Heat can affect network equipment by:','["making them faster", "adding memory", "causing devices to fail or slow down", "cleaning them"]'::jsonb,2,'Overheating damages equipment.','original'),
('127.681.d.6.B',4,'Which environmental factor can cause interference with unshielded network cables?','["a coat rack", "a painted wall", "a quiet hallway", "nearby electrical motors or fluorescent lights"]'::jsonb,3,'Electrical noise interferes with signals.','original'),
('127.681.d.6.C',3,'An Ethernet port on a computer is also called a:','["LAN port", "HDMI cable", "audio mix", "USB drive"]'::jsonb,0,'It connects to the LAN.','original'),
('127.681.d.6.C',4,'A device that connects several computers and passes traffic between their ports is a:','["microphone", "switch", "scanner", "monitor"]'::jsonb,1,'Switches connect multiple hosts.','original'),
('127.681.d.6.D',3,'A subnetting chart lists the:','["employee salaries", "paint colors", "address ranges for each subnet", "parking spots"]'::jsonb,2,'The chart organizes subnet ranges.','original'),
('127.681.d.6.D',4,'A subnet mask of 255.255.255.0 means the first three parts of the address identify the:','["user name", "host only", "printer", "network"]'::jsonb,3,'The mask separates network from host.','original'),
('127.681.d.6.E',3,'A cable tester is used to:','["check that a cable is wired correctly", "measure room size", "play music", "print documents"]'::jsonb,0,'Testers check continuity and wiring.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
